const HEADER = ['order_id', 'date', 'customer_name', 'email', 'shipping_state', 'subtotal', 'total', 'status'];

export function ordersToCsv(orders: OrderWithCustomer[]): string {
  const rows = orders.map(o => [
    o.id,
    o.createdAt.toISOString().slice(0, 10),
    o.customer.name,
    o.customer.email,
    o.shippingState ?? '',
    o.subtotal.toFixed(2),
    o.total.toFixed(2),
    o.status,
  ].join(','));
  return [HEADER.join(','), ...rows].join('\n');
}
"}

