{"path": "src/server/incidents.ts", "content": "import { replica } from './db';

export type Incident = {
  id: number;
  ruleId: string;
  title: string;
  status: 'open' | 'acknowledged' | 'resolved';
  openedAt: string;
};

export type Page = { items: Incident[]; total: number; page: number; pageSize: number };

export const PAGE_SIZE = 50;

export async function listIncidents(page = 1, pageSize = PAGE_SIZE): Promise<Page> {
  const offset = (Math.max(1, page) - 1) * pageSize;
  const { rows } = await replica.query(
    `SELECT id, rule_id AS "ruleId", title, status,
            to_char(opened_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') AS "openedAt",
            count(*) OVER () AS total
       FROM incidents
      ORDER BY opened_at DESC, id DESC
      LIMIT $1 OFFSET $2`,
    [pageSize, offset],
  );
  return {
    items: rows.map(({ total: _t, ...i }) => i),
    total: rows.length ? Number(rows[0].total) : 0,
    page,
    pageSize,
  };
}
"}

