import { getIncidents } from '../api';
import type { Page } from '../../server/incidents';

export function Incidents() {
  const [page, setPage] = useState(1);
  const [data, setData] = useState<Page | null>(null);
  useEffect(() => {
    getIncidents(page).then(setData);
  }, [page]);

  const pageCount = data ? Math.max(1, Math.ceil(data.total / data.pageSize)) : 1;

  return (
    <section>
      <h2>Incidents</h2>
      <table>
        <thead>
          <tr><th>Opened</th><th>Title</th><th>Rule</th><th>Status</th></tr>
        </thead>
        <tbody>
          {data?.items.map((i) => (
            <tr key={i.id}>
              <td>{new Date(i.openedAt).toLocaleString()}</td>
              <td>{i.title}</td>
              <td><code>{i.ruleId}</code></td>
              <td>{i.status}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <footer>
        <button onClick={() => setPage(page - 1)} disabled={page <= 1}>Previous</button>
        {Array.from({ length: pageCount }, (_, i) => i + 1).map((n) => (
          <button key={n} onClick={() => setPage(n)} disabled={n === page} aria-current={n === page}>
            {n}
          </button>
        ))}
        <button onClick={() => setPage(page + 1)} disabled={page >= pageCount}>Next</button>
      </footer>
    </section>
  );
}
"}

