// Merge changed rules into the file by id. Rules not in `changes` keep their current
// values, so edits by other people to other rules are not overwritten.
export async function patchRules(changes: Partial<Rule>[], path = RULES_PATH): Promise<void> {
  const current = await loadRules(path);
  const byId = new Map(current.map((r) => [r.id, r]));
  const problems: string[] = [];
  for (const c of changes) {
    if (!c.id || !byId.has(c.id)) {
      problems.push(`unknown rule id ${c.id ?? '(missing)'}`);
      continue;
    }
    // The id is the key incidents use to find their rule, so it can't be changed here.
    byId.set(c.id, { ...byId.get(c.id)!, ...c, id: c.id });
  }
  if (problems.length) throw new Error(problems.join('; '));
  await saveRules([...byId.values()], path);
}"}

