// Merges edited rules into the file by id. Only the given rules change; the rest of the file
// is kept as it is on disk now, so edits from other people are not overwritten.
// Merges run one at a time so two concurrent saves cannot read the same file and drop each other's change.
let queue: Promise<void> = Promise.resolve();

export function mergeRules(changed: Rule[], path = RULES_PATH): Promise<void> {
  const run = queue.then(() => doMerge(changed, path));
  queue = run.catch(() => {});
  return run;
}

async function doMerge(changed: Rule[], path: string): Promise<void> {
  const current = await loadRules(path);
  const edits = new Map(changed.map((r) => [r.id, r]));
  const unknown = [...edits.keys()].filter((id) => !current.some((r) => r.id === id));
  if (unknown.length) throw new Error(`unknown rule ids: ${unknown.join(', ')}`);
  await saveRules(current.map((r) => edits.get(r.id) ?? r), path);
