  if (!r.name.trim()) return `${r.id}: name is empty`;
  if (!Number.isFinite(r.threshold)) return `${r.id}: threshold must be a number`;
  if (!['info', 'warning', 'critical'].includes(r.severity)) return `${r.id}: unknown severity ${r.severity}`;
